  'content.tarot.51.reversed': 'La venda cae, surge una decisión o por fin se rompe el estancamiento.',
  'content.tarot.51.socratic': '¿Qué sabrías si dejaras de negarte a mirar?',
  'content.tarot.50.name': 'As de Espadas',
