  'content.tarot.50.keyword.1': 'Verdad',
  'content.tarot.50.keyword.2': 'Descubrimiento',
  'content.tarot.50.upright': 'La verdad, como una espada de doble filo, atraviesa la niebla: un avance que exige honestidad.',
  'content.tarot.50.reversed': 'Lucidez empañada, palabras utilizadas como armas o claridad que se vuelve en tu contra.',
  'content.tarot.50.socratic': '¿Qué verdad, una vez dicha, reduciría tu problema a la mitad?',
  'content.tarot.49.name': 'Rey de Copas',
