  'content.tarot.41.keyword.1': 'Inocencia',
  'content.tarot.41.keyword.2': 'Memoria',
  'content.tarot.41.upright': 'Regalos del pasado: recuerdos que nutren en lugar de aprisionar.',
  'content.tarot.41.reversed': 'Vivir anclado en el pasado, idealizar lo que fue o negarse a crecer más allá del jardín.',
  'content.tarot.41.socratic': '¿El pasado te está alimentando o lo estás alimentando tú?',
