  'content.lenormand.2.keyword.0': 'Suerte',
  'content.lenormand.2.keyword.1': 'Oportunidad',
  'content.lenormand.2.keyword.2': 'Ligereza',
  'content.lenormand.2.meaning': 'Un pequeño golpe de suerte y un corazón más alegre: aprovecha el momento mientras la puerta permanece abierta.',
  'content.lenormand.2.combination.0': 'Con el Sol, la suerte se convierte en éxito.',
